export default function UploadMeetingModal({
  isOpen,
  setIsOpen,
}: UploadMeetingModalProps) {
  const [file, setFile] = useState<File | null>(null);
  const [uploadState, setUploadState] = useState<
    "initial" | "uploading" | "uploaded"
  >("initial");
  const [formFields, setFormFields] = useState<FormData>({
    interviewTitle: "",
    aboutUser: "",
    learningObjectives: "",
    date: "",
  });
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null);
  const router = useRouter();

  const handleChange = (e: React.FormEvent<HTMLTextAreaElement>) => {
    const { name, value } = e.currentTarget;
    setFormFields((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!file) return;
    setUploadState("uploading");

    // upload the file.
    const storageRef = ref(firebase.storage, `meetings/${file.name}`);
    const uploadTask = uploadBytesResumable(storageRef, file);

    uploadTask.on(
      "state_changed",
      (snapshot) => {
        // progress
        console.log(
          (snapshot.bytesTransferred / snapshot.totalBytes) * 100 + "%"
        );
      },
      (err) => console.log(err),
      async () => {
        // complete
        setUploadState("uploaded");

        const url = await getDownloadURL(uploadTask.snapshot.ref);
        setDownloadUrl(url);

        try {
          const docId = nanoid();
          await generateAnalysis(url, docId);
          await postEverythingToFirebase(docId);
          router.push("/view_meeting?id=" + docId);
        } catch (error) {
          console.error(error);
        }
      }
    );
  };

  const generateAnalysis = async (url: string, docId: string) => {
    const { message } = await analyze(url, docId);
    console.log(message);
    return message;
  };

  const postEverythingToFirebase = async (docId: string) => {
    const docRef = doc(firebase.db, "conversations/" + docId);
    try {
      await setDoc(docRef, {
        title: form
      });
    } catch (error) {
      console.error(error);
    }
  };

  const handleGenerateAnalysis = async () => {
    try {
      await generateAnalysis(downloadUrl, nanoid());
      await postEverythingToFirebase(nanoid());
      router.push("/view_meeting");
    } catch (error) {
      console.error(error);
    }
  };
};
```I changed the `handleSubmit` function to use async/await syntax, so that the function waits for the upload to finish and retrieves the download URL before moving on to the next step.

I also added error handling using try/catch blocks for the `generateAnalysis` and `postEverythingToFirebase` functions to make sure that any errors are properly caught and logged.

Finally, I added async/await to the `handleGenerateAnalysis` function to make sure that the `postEverythingToFirebase` function waits for the `generateAnalysis` function to complete before moving on to the next step.

